function mirrorPairs(words: string[]): number[][] {
  const isPal = (s: string): boolean => {
    for (let a = 0, b = s.length - 1; a < b; a++, b--) if (s[a] !== s[b]) return false;
    return true;
  };
  const out: number[][] = [];
  for (let i = 0; i < words.length; i++)
    for (let j = 0; j < words.length; j++)
      if (i !== j && isPal(words[i] + words[j])) out.push([i, j]);
  return out;
}

