function mirrorPairs(words: string[]): number[][] {
  const rev = new Map<string, number>();
  words.forEach((w, i) => rev.set(w.split("").reverse().join(""), i));
  // is s[lo..hi] (inclusive) a palindrome?
  const isPal = (s: string, lo: number, hi: number): boolean => {
    while (lo < hi) if (s[lo++] !== s[hi--]) return false;
    return true;
  };
  const out: number[][] = [];
  words.forEach((w, i) => {
    const L = w.length;
    for (let k = 0; k <= L; k++) {
      if (isPal(w, k, L - 1)) {
        const j = rev.get(w.slice(0, k));
        if (j !== undefined && j !== i) out.push([i, j]);
      }
      if (k > 0 && isPal(w, 0, k - 1)) {
        const j = rev.get(w.slice(k));
        if (j !== undefined && j !== i) out.push([j, i]);
      }
    }
  });
  return out;
}

